/* Shader+ rows reuse CM3's native controls; these rules only size and
   color the pieces CM3 has no equivalent for, with the theme tokens. */
.zsp-property,.zsp-property > div { min-width: 0; }
.zsp-box { min-width: 0; max-width: 100%; box-sizing: border-box; }
.zsp-box input,.zsp-box select,.zsp-box textarea { box-sizing: border-box; max-width: 100%; }
.zsp-box [hidden],.zsp-property[hidden] { display: none !important; }
.zsp-anchor { display: none; }
.zsp-option { width: auto; max-width: 100%; }
.zsp-inline-row,.zsp-slider { display: flex; align-items: center; gap: 6px; min-width: 0; }
.zsp-slider > :first-child,.zsp-inline-row > :first-child { flex: 0 0 auto; }

/* Slider: theme-colored track and thumb instead of the browser default. */
.zsp-range { flex: 1 1 60px; min-width: 40px; height: 16px; margin: 0 4px 0 0; appearance: none; -webkit-appearance: none; background: transparent; cursor: pointer; }
.zsp-range::-webkit-slider-runnable-track { height: 4px; border-radius: 2px; background: linear-gradient(to right,var(--zui-value) var(--zsp-fill,0%),var(--zui-bg-input) var(--zsp-fill,0%)); box-shadow: inset 0 0 0 1px var(--zui-border-filter); }
